<?php
namespace Tests\Feature;
use App\Models\Company;use App\Models\User;use Illuminate\Foundation\Testing\RefreshDatabase;use Tests\TestCase;
class AdminCompanyModerationTest extends TestCase{use RefreshDatabase;public function test_admin_can_review_pending_company():void{$owner=User::factory()->create(['account_type'=>'company']);$company=Company::create(['name'=>'Acme','slug'=>'acme','status'=>'active','verification_status'=>'pending','verification_submitted_at'=>now()]);$company->members()->attach($owner->id,['role'=>'owner','status'=>'active']);$admin=User::factory()->create(['is_admin'=>true]);$this->actingAs($admin,'sanctum')->getJson('/api/v1/admin/moderation')->assertOk()->assertJsonCount(1,'data.companies');$this->actingAs($admin,'sanctum')->postJson("/api/v1/admin/companies/{$company->id}/review",['decision'=>'approve','note'=>'Datos validados.'])->assertOk()->assertJsonPath('data.verification_status','verified');$this->assertDatabaseHas('companies',['id'=>$company->id,'verification_reviewed_by'=>$admin->id,'verification_review_note'=>'Datos validados.']);}public function test_non_admin_cannot_review_company():void{$company=Company::create(['name'=>'Acme','slug'=>'acme','status'=>'active','verification_status'=>'pending']);$this->actingAs(User::factory()->create(),'sanctum')->postJson("/api/v1/admin/companies/{$company->id}/review",['decision'=>'approve'])->assertForbidden();}}
